-- Fixture hands, one per shape the readers must get right, and what each seat
-- truly won or lost (chips won minus every chip put in, ante included). No
-- hole cards: the readers never read them and the fixture holds none.
--
--   a1  ordinary NLH, blinds posted, uncalled flop bet returned
--   a2  big-blind-ante game (ante row dead), rake taken
--   a3  straddle, split pot
--   a4  side pots: short all-in wins the main pot, another seat the side pot
--   a5  legacy log with no post rows: blinds synthesised from position
--   b1  timed bomb pot, the shape of production hand b06f6fc5 (split, rake)
--   b2  timed bomb pot, the shape of production hand 41c06d33 (split, rake)
--   b3  heads-up timed bomb pot, uncalled flop bet returned
--   b4  bomb pot marked only by its bomb_ante rows (hand_history.bomb_pot NULL)
CREATE TABLE public.bomb_proof_expected (
  hand_id uuid, user_id uuid, profit numeric, my_blind numeric, put_in numeric,
  PRIMARY KEY (hand_id, user_id)
);

